if (!/<header[\s>][\s\S]*?<\/header>/i.test(code)) {
  throw new Error("Wrap the site name in a <header> element.");
}

const nav = code.match(/<nav[\s>][\s\S]*?<\/nav>/i);
if (!nav) {
  throw new Error("Put the navigation links in a <nav> element.");
}
if (!/<nav[^>]*>[\s\S]*?<a\s[^>]*href=/i.test(nav[0])) {
  throw new Error("The <nav> must contain the two <a> links.");
}

const mains = (code.match(/<main[\s>]/gi) || []).length;
if (mains !== 1) {
  throw new Error("A page has exactly one <main> element (found " + mains + ").");
}
const mainEl = code.match(/<main[\s>][\s\S]*?<\/main>/i);
if (!mainEl || !/<h2/i.test(mainEl[0])) {
  throw new Error("The page content (the sections with their <h2>s) must live inside <main>.");
}

const sections = code.match(/<section[\s>][\s\S]*?<\/section>/gi) || [];
if (sections.length < 2) {
  throw new Error("Turn both content blocks into <section> elements.");
}
for (const s of sections) {
  if (!/<h2/i.test(s)) {
    throw new Error("Each <section> must keep its own heading.");
  }
}

const footer = code.match(/<footer[\s>][\s\S]*?<\/footer>/i);
if (!footer || !/©|copyright/i.test(footer[0])) {
  throw new Error("Add a <footer> containing the copyright paragraph.");
}
